int longestUnique(const std::string& s) {
    std::array<int, 256> last;
    last.fill(-1);
    int left = 0, best = 0;
    for (int right = 0; right < (int)s.size(); ++right) {
        unsigned char c = s[right];
        if (last[c] >= left) left = last[c] + 1;
        last[c] = right;
        best = std::max(best, right - left + 1);
    }
    return best;
}
// O(n) time, O(1) space (fixed 256-entry table).

class RunningMedian {
    std::priority_queue<int> lo;                                   // max-heap, lower half
    std::priority_queue<int, std::vector<int>, std::greater<>> hi; // min-heap, upper half
public:
    void add(int x) {
        if (lo.empty() || x <= lo.top()) lo.push(x); else hi.push(x);
        if (lo.size() > hi.size() + 1) { hi.push(lo.top()); lo.pop(); }
        else if (hi.size() > lo.size()) { lo.push(hi.top()); hi.pop(); }
    }
    double median() const {
        if (lo.size() == hi.size()) return (lo.top() + hi.top()) / 2.0;
        return lo.top();
    }
};
// add: O(log n), median: O(1), space: O(n).

bool hasCycle(int n, const std::vector<std::vector<int>>& adj) {
    std::vector<int> color(n, 0); // 0 white, 1 gray, 2 black
    std::function<bool(int)> dfs = [&](int u) {
        color[u] = 1;
        for (int v : adj[u]) {
            if (color[v] == 1) return true;           // back edge
            if (color[v] == 0 && dfs(v)) return true;
        }
        color[u] = 2;
        return false;
    };
    for (int i = 0; i < n; ++i)
        if (color[i] == 0 && dfs(i)) return true;
    return false;
}
// O(V + E) time, O(V) space.
